messages.content:
Write a single self-contained HTML file with a 3D animation using three.js. three.js r160 is available as an ES module at './three.module.js' -- import it with:
  import * as THREE from './three.module.js';
Scene: two cars race on a straight track toward a visible finish line. One car is bright RED, the other bright BLUE. The blue car leads early, then the red car accelerates, overtakes mid-race, and wins. After the red car crosses the finish line the race resets and loops forever. Both cars must be clearly visible and large enough to follow throughout (fill a meaningful part of the frame). Simple ground and sky, camera keeps both cars in view. No external assets besides the three.js import. Output ONLY the HTML in one code block.

response.text:
```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Red vs Blue 3D Race</title>
    <style>
        body { margin: 0; overflow: hidden; background-color: #87CEEB; }
        canvas { display: block; width: 100vw; height: 100vh; }
    </style>
</head>
<body>
    <script type="module">
        import * as THREE from './three.module.js';

        // --- Configuration ---
        const RACE_DURATION = 1000; // Frames for a full race
        const TRACK_LENGTH = 400;

        // --- Scene Setup ---
        const scene = new THREE.Scene();
        scene.background = new THREE.Color(0x87CEEB); // Sky blue
        scene.fog = new THREE.Fog(0x87CEEB, 20, 150);

        const camera = new THREE.PerspectiveCamera(60, window.innerWidth / window.innerHeight, 0.1, 1000);
        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.shadowMap.enabled = true;
        document.body.appendChild(renderer.domElement);

        // --- Lighting ---
        const ambientLight = new THREE.AmbientLight(0xffffff, 0.6);
        scene.add(ambientLight);

        const dirLight = new THREE.DirectionalLight(0xffffff, 1);
        dirLight.position.set(50, 100, 50);
        dirLight.castShadow = true;
        dirLight.shadow.camera.left = -50;
        dirLight.shadow.camera.right = 50;
        dirLight.shadow.camera.top = 50;
        dirLight.shadow.camera.bottom = -50;
        scene.add(dirLight);

        // --- Environment ---
        // Ground
        const groundGeo = new THREE.PlaneGeometry(200, TRACK_LENGTH + 200);
        const groundMat = new THREE.MeshLambertMaterial({ color: 0x4caf50 });
        const ground = new THREE.Mesh(groundGeo, groundMat);
        ground.rotation.x = -Math.PI / 2;
        ground.position.z = -TRACK_LENGTH / 2;
        ground.receiveShadow = true;
        scene.add(ground);

        // Road
        const roadGeo = new THREE.PlaneGeometry(40, TRACK_LENGTH + 200);
        const roadMat = new THREE.MeshLambertMaterial({ color: 0x333333 });
        const road = new THREE.Mesh(roadGeo, roadMat);
        road.rotation.x = -Math.PI / 2;
        road.position.z = -TRACK_LENGTH / 2;
        road.position.y = 0.05; // Slightly above ground
        road.receiveShadow = true;
        scene.add(road);

        // Finish Line
        const finishLineGeo = new THREE.PlaneGeometry(40, 4);
        const finishLineMat = new THREE.MeshBasicMaterial({ color: 0xffffff }); // Checkered simplified to white
        const finishLine = new THREE.Mesh(finishLineGeo, finishLineMat);
        finishLine.rotation.x = -Math.PI / 2;
        finishLine.position.set(0, 0.06, -TRACK_LENGTH);
        scene.add(finishLine);

        // Finish Banner
        const bannerGeo = new THREE.BoxGeometry(42, 5, 1);
        const bannerMat = new THREE.MeshBasicMaterial({ color: 0xff0000 });
        const banner = new THREE.Mesh(bannerGeo, bannerMat);
        banner.position.set(0, 5, -TRACK_LENGTH);
        scene.add(banner);

        // --- Car Factory ---
        function createCar(color) {
            const carGroup = new THREE.Group();

            // Chassis
            const chassisGeo = new THREE.BoxGeometry(2.5, 1, 5);
            const chassisMat = new THREE.MeshStandardMaterial({ color: color });
            const chassis = new THREE.Mesh(chassisGeo, chassisMat);
            chassis.position.y = 0.75;
            chassis.castShadow = true;
            carGroup.add(chassis);

            // Cabin
            const cabinGeo = new THREE.BoxGeometry(2.2, 0.8, 2.5);
            const cabinMat = new THREE.MeshStandardMaterial({ color: 0x222222 }); // Dark windows
            const cabin = new THREE.Mesh(cabinGeo, cabinMat);
            cabin.position.set(0, 1.5, -0.25);
            cabin.castShadow = true;
            carGroup.add(cabin);

            // Wheels
            const wheelGeo = new THREE.CylinderGeometry(0.5, 0.5, 0.4, 24);
            const wheelMat = new THREE.MeshStandardMaterial({ color: 0x111111 });
            wheelGeo.rotateZ(Math.PI / 2);

            const positions = [
                { x: -1.3, y: 0.5, z: 1.5 },
                { x: 1.3, y: 0.5, z: 1.5 },
                { x: -1.3, y: 0.5, z: -1.5 },
                { x: 1.3, y: 0.5, z: -1.5 }
            ];

            positions.forEach(pos => {
                const wheel = new THREE.Mesh(wheelGeo, wheelMat);
                wheel.position.set(pos.x, pos.y, pos.z);
                wheel.castShadow = true;
                carGroup.add(wheel);
            });

            // Spoiler
            const spoilerGeo = new THREE.BoxGeometry(3, 0.1, 0.5);
            const spoiler = new THREE.Mesh(spoilerGeo, new THREE.MeshStandardMaterial({color: color}));
            spoiler.position.set(0, 1.5, -2.4);
            carGroup.add(spoiler);

            const spoilerStandGeo = new THREE.BoxGeometry(0.2, 0.5, 0.2);
            const standL = new THREE.Mesh(spoilerStandGeo, new THREE.MeshStandardMaterial({color: 0x111111}));
            standL.position.set(-1, 1.2, -2.4);
            const standR = new THREE.Mesh(spoilerStandGeo, new THREE.MeshStandardMaterial({color: 0x111111}));
            standR.position.set(1, 1.2, -2.4);
            carGroup.add(standL);
            carGroup.add(standR);

            return carGroup;
        }

        const redCar = createCar(0xff0000);
        const blueCar = createCar(0x0000ff);
        scene.add(redCar);
        scene.add(blueCar);

        // --- Animation Logic ---
        let frame = 0;

        // Initial positions
        const startZ = 0;
        redCar.position.set(6, 0, startZ);
        blueCar.position.set(-6, 0, startZ);

        // Camera smoothing variables
        const cameraLerp = 0.1;

        function easeInOutQuad(t) {
            return t < 0.5 ? 2 * t * t : -1 + (4 - 2 * t) * t;
        }

        function animate() {
            requestAnimationFrame(animate);

            frame++;
            const progress = frame / RACE_DURATION; // 0 to 1

            // --- Movement Logic ---

            // Blue Car Logic: Leads early, gets overtaken
            // We want it to be ahead at t=0.3, behind at t=0.6, and finish last.
            // Using a custom curve approximation for position based on progress.
            // Simple approach: Base speed + acceleration burst

            let bluePos, redPos;

            // Blue Car: Fast start, slows down slightly in middle, finishes
            // Formula: Position = Distance * (Custom Curve)
            // Let's use a polynomial to define the race narrative
            // Blue: Starts fast (t^2), slows ( -t^3 )
            let blueRaw = 1.3 * progress - 0.3 * Math.pow(progress, 2); // Starts faster relative to red
            // Normalize so it actually reaches the end at the right time (slightly after red)
            // Let's hardcode the "Overtake" moment logic instead of pure math for better control.

            // Narrative positions (0 to TRACK_LENGTH)
            // At 20%: Blue is ahead.
            // At 50%: Red passes Blue.
            // At 90%: Red wins.

            // Blue Position
            bluePos = -TRACK_LENGTH * (progress * 0.95); // Finishes slightly after red

            // Red Position
            // Needs to start slower, accelerate hard.
            // Use a sigmoid-like curve or power function
            let redRaw = Math.pow(progress, 1.8); 
            redPos = -TRACK_LENGTH * redRaw;

            // Apply positions
            blueCar.position.z = bluePos;
            redCar.position.z = redPos;

            // Add some "drift" or "wobble" to make it look alive
            const wobble = Math.sin(frame * 0.2) * 0.1;
            redCar.position.x = 6 + wobble;
            blueCar.position.x = -6 - wobble;

            // Tilt cars slightly on turns (simulated by wobble)
            redCar.rotation.z = -wobble * 0.1;
            blueCar.rotation.z = wobble * 0.1;

            // --- Camera Logic ---
            // Calculate center point between cars
            const midZ = (redCar.position.z + blueCar.position.z) / 2;
            const midX = (redCar.position.x + blueCar.position.x) / 2;

            // Distance between cars determines camera height and distance
            const distZ = Math.abs(redCar.position.z - blueCar.position.z);

            // Ideal camera position
            const camOffsetZ = 25 + (distZ * 0.4); // Zoom out if they spread apart
            const camHeight = 15 + (distZ * 0.1);

            const targetCamPos = new THREE.Vector3(midX, camHeight, midZ + camOffsetZ);

            // Smoothly interpolate camera position
            camera.position.lerp(targetCamPos, cameraLerp);

            // Look at the midpoint slightly ahead
            const lookTarget = new THREE.Vector3(midX, 0, midZ - 20);
            camera.lookAt(lookTarget);

            // --- Looping ---
            if (frame > RACE_DURATION) {
                frame = 0;
                // Reset positions instantly
                redCar.position.set(6, 0, startZ);
                blueCar.position.set(-6, 0, startZ);
                // Reset camera to avoid snapping
                camera.position.set(0, 15, 25);
                camera.lookAt(0, 0, -20);
            }

            renderer.render(scene, camera);
        }

        // Handle Resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();
    </script>
</body>
</html>
```
